package com.bank.salary.service;

import com.bank.salary.dto.SalaryReport;
import com.bank.salary.model.Employee;
import lombok.extern.slf4j.Slf4j;
import org.springframework.stereotype.Service;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Collectors;

@Service
@Slf4j
public class SalaryRankingService {

    private final List<Employee> employees = List.of(
        new Employee("E001", "Rajesh Kumar",  "TRADING",    new BigDecimal("1200000")),
        new Employee("E002", "Priya Sharma",  "RISK",       new BigDecimal("1000000")),
        new Employee("E003", "Amit Patel",    "TRADING",    new BigDecimal("1500000")),
        new Employee("E004", "Deepa Reddy",   "OPERATIONS", new BigDecimal("900000")),
        new Employee("E005", "Vikram Singh",  "RISK",       new BigDecimal("1800000")),
        new Employee("E006", "Neha Gupta",    "TRADING",    new BigDecimal("1100000")),
        new Employee("E007", "Suresh Iyer",   "OPERATIONS", new BigDecimal("1400000")),
        new Employee("E008", "Kavita Joshi",  "RISK",       new BigDecimal("1000000")),  // same as Priya!
        new Employee("E009", "Rohit Mehta",   "COMPLIANCE", new BigDecimal("1300000")),
        new Employee("E010", "Anita Desai",   "COMPLIANCE", new BigDecimal("1050000"))
    );

    public SalaryReport generateReport(int n) {

        // ═══ 1. HIGHEST salary ═══
        String highest = employees.stream()
            .map(Employee::salary)
            .max(Comparator.naturalOrder())
            .map(s -> "Rs." + s)
            .orElse("No employees");
        log.info("Highest salary: {}", highest);

        // ═══ 2. SECOND-HIGHEST salary (distinct — Rs.10L appears twice!) ═══
        String secondHighest = employees.stream()
            .map(Employee::salary)
            .distinct()                                          // remove duplicate Rs.10L
            .sorted(Comparator.reverseOrder())                   // descending
            .skip(1)                                             // skip highest (Rs.18L)
            .findFirst()                                         // second (Rs.15L)
            .map(s -> "Rs." + s)
            .orElse("Not enough distinct salaries");
        log.info("2nd highest salary: {}", secondHighest);

        // ═══ 3. Nth-HIGHEST salary ═══
        String nthHighest = employees.stream()
            .map(Employee::salary)
            .distinct()
            .sorted(Comparator.reverseOrder())
            .skip((long) n - 1)
            .findFirst()
            .map(s -> "Rs." + s + " (rank " + n + ")")
            .orElse("N exceeds distinct salary count");
        log.info("{}th highest: {}", n, nthHighest);

        // ═══ 4. TOP 3 EARNERS (employees, not just salaries) ═══
        List<String> top3 = employees.stream()
            .sorted(Comparator.comparing(Employee::salary).reversed())
            .limit(3)
            .map(e -> e.name() + " — Rs." + e.salary() + " (" + e.department() + ")")
            .toList();
        log.info("Top 3 earners: {}", top3);

        // ═══ 5. FULL SALARY RANKING ═══
        List<String> ranking = new ArrayList<>();
        List<Employee> sorted = employees.stream()
            .sorted(Comparator.comparing(Employee::salary).reversed())
            .toList();
        for (int i = 0; i < sorted.size(); i++) {
            Employee e = sorted.get(i);
            ranking.add("#" + (i + 1) + " " + e.name() + " — Rs." + e.salary());
        }

        // ═══ 6. TOP 2 PER DEPARTMENT ═══
        Map<String, List<String>> top2PerDept = employees.stream()
            .collect(Collectors.groupingBy(Employee::department))
            .entrySet().stream()
            .collect(Collectors.toMap(
                Map.Entry::getKey,
                entry -> entry.getValue().stream()
                    .sorted(Comparator.comparing(Employee::salary).reversed())
                    .limit(2)
                    .map(e -> e.name() + " Rs." + e.salary())
                    .toList()
            ));
        log.info("Top 2 per dept: {}", top2PerDept);

        return new SalaryReport(highest, secondHighest, nthHighest, n,
            top3, ranking, top2PerDept);
    }
}
