package com.bank.salary.service;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import java.util.stream.Stream;
import static org.assertj.core.api.Assertions.*;

class NthHighestSalaryTest {

    List<BigDecimal> salaries = List.of(
        bd("1200000"), bd("1000000"), bd("1500000"), bd("900000"),
        bd("1800000"), bd("1000000"), bd("1400000"));  // 1000000 duplicated

    @Test
    void highestSalary() {
        Optional<BigDecimal> max = salaries.stream().max(Comparator.naturalOrder());
        assertThat(max).contains(bd("1800000"));
    }

    @Test
    void secondHighestDistinct() {
        Optional<BigDecimal> second = salaries.stream()
            .distinct().sorted(Comparator.reverseOrder()).skip(1).findFirst();
        assertThat(second).contains(bd("1500000"));  // NOT 1800000 (that's first)
    }

    @Test
    void thirdHighestDistinct() {
        Optional<BigDecimal> third = salaries.stream()
            .distinct().sorted(Comparator.reverseOrder()).skip(2).findFirst();
        assertThat(third).contains(bd("1400000"));
    }

    @Test
    void nthHighestBeyondRange() {
        Optional<BigDecimal> beyond = salaries.stream()
            .distinct().sorted(Comparator.reverseOrder()).skip(100).findFirst();
        assertThat(beyond).isEmpty();  // N exceeds distinct count
    }

    @Test
    void top3Salaries() {
        List<BigDecimal> top3 = salaries.stream()
            .sorted(Comparator.reverseOrder())
            .limit(3)
            .toList();
        assertThat(top3).containsExactly(bd("1800000"), bd("1500000"), bd("1400000"));
    }

    @Test
    void distinctMattersForDuplicates() {
        // Without distinct: skip(1) gives 1500000 (second OCCURRENCE, same as with distinct here)
        // But if highest is duplicated:
        List<BigDecimal> withDupMax = List.of(bd("100"), bd("100"), bd("90"), bd("80"));

        // Without distinct: skip(1) gives 100 (the duplicate!)
        Optional<BigDecimal> wrongSecond = withDupMax.stream()
            .sorted(Comparator.reverseOrder()).skip(1).findFirst();
        assertThat(wrongSecond).contains(bd("100"));  // WRONG! Still 100!

        // With distinct: skip(1) gives 90 (correct second-highest)
        Optional<BigDecimal> correctSecond = withDupMax.stream()
            .distinct().sorted(Comparator.reverseOrder()).skip(1).findFirst();
        assertThat(correctSecond).contains(bd("90"));  // CORRECT!
    }

    private BigDecimal bd(String v) { return new BigDecimal(v); }
}
